import React from 'react'
import { AlertTriangle, RefreshCw, Home } from 'lucide-react'

/**
 * ErrorBoundary - Catches JavaScript errors in child components
 * 
 * This component prevents the entire app from crashing when a component
 * encounters an unhandled error. Instead, it shows a user-friendly error
 * message with recovery options.
 * 
 * @example
 * <ErrorBoundary fallback={<CustomErrorUI />}>
 *   <MyComponent />
 * </ErrorBoundary>
 */
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props)
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    }
  }

  static getDerivedStateFromError(error) {
    // Update state so the next render shows the fallback UI
    return { hasError: true, error }
  }

  componentDidCatch(error, errorInfo) {
    // Log the error to console for debugging
    console.error('ErrorBoundary caught an error:', error, errorInfo)

    this.setState({
      error,
      errorInfo,
    })

    // You could also log to an error reporting service here
    // logErrorToService(error, errorInfo)
  }

  handleReload = () => {
    window.location.reload()
  }

  handleGoHome = () => {
    window.location.href = '/'
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null, errorInfo: null })
  }

  render() {
    if (this.state.hasError) {
      // Custom fallback UI if provided
      if (this.props.fallback) {
        return this.props.fallback
      }

      // Default error UI
      return (
        <div
          className="min-h-[400px] flex items-center justify-center p-8"
          role="alert"
          aria-live="assertive"
        >
          <div className="max-w-md w-full glass rounded-3xl p-8 text-center">
            <div className="w-16 h-16 rounded-2xl bg-red-500/10 flex items-center justify-center mx-auto mb-6">
              <AlertTriangle className="w-8 h-8 text-red-400" aria-hidden="true" />
            </div>

            <h2 className="text-xl font-semibold text-white mb-2">
              Something went wrong
            </h2>

            <p className="text-slate-400 mb-6">
              We encountered an unexpected error. Please try again or return to the home page.
            </p>

            {/* Show error details in development */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mb-6 text-left">
                <summary className="text-slate-500 text-sm cursor-pointer hover:text-slate-400 transition-colors">
                  Error details
                </summary>
                <pre className="mt-2 p-4 bg-slate-800/50 rounded-xl text-xs text-red-400 overflow-auto max-h-40">
                  {this.state.error.toString()}
                  {this.state.errorInfo?.componentStack}
                </pre>
              </details>
            )}

            <div className="flex flex-col sm:flex-row gap-3">
              <button
                onClick={this.handleRetry}
                className="flex-1 py-3 px-4 bg-medical-500 hover:bg-medical-400 text-white rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-medical-300"
                aria-label="Try again"
              >
                <RefreshCw className="w-4 h-4" aria-hidden="true" />
                Try Again
              </button>

              <button
                onClick={this.handleGoHome}
                className="flex-1 py-3 px-4 bg-slate-700 hover:bg-slate-600 text-white rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-slate-500"
                aria-label="Go to home page"
              >
                <Home className="w-4 h-4" aria-hidden="true" />
                Go Home
              </button>
            </div>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

/**
 * RouteErrorBoundary - A simpler error boundary for route-level errors
 * Shows a full-page error state with navigation options
 */
class RouteErrorBoundary extends ErrorBoundary {
  render() {
    if (this.state.hasError) {
      return (
        <div
          className="min-h-screen animated-gradient grid-bg flex items-center justify-center p-8"
          role="alert"
          aria-live="assertive"
        >
          <div className="max-w-lg w-full glass rounded-3xl p-8 text-center">
            <div className="w-20 h-20 rounded-2xl bg-red-500/10 flex items-center justify-center mx-auto mb-6">
              <AlertTriangle className="w-10 h-10 text-red-400" aria-hidden="true" />
            </div>

            <h1 className="text-2xl font-bold text-white mb-3">
              Oops! Something went wrong
            </h1>

            <p className="text-slate-400 mb-8 leading-relaxed">
              We&apos;re sorry, but this page encountered an error.
              Our team has been notified and is working on a fix.
            </p>

            {/* Show error in development */}
            {process.env.NODE_ENV === 'development' && this.state.error && (
              <div className="mb-6 p-4 bg-slate-800/50 rounded-xl text-left">
                <p className="text-red-400 text-sm font-mono break-all">
                  {this.state.error.toString()}
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-4">
              <button
                onClick={this.handleReload}
                className="flex-1 py-4 px-6 bg-gradient-to-r from-medical-500 to-medical-600 hover:from-medical-400 hover:to-medical-500 text-white font-semibold rounded-xl shadow-lg shadow-medical-500/25 transition-all flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-medical-300"
                aria-label="Reload this page"
              >
                <RefreshCw className="w-5 h-5" aria-hidden="true" />
                Reload Page
              </button>

              <button
                onClick={this.handleGoHome}
                className="flex-1 py-4 px-6 bg-slate-700 hover:bg-slate-600 text-white font-semibold rounded-xl transition-colors flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-slate-500"
                aria-label="Return to home page"
              >
                <Home className="w-5 h-5" aria-hidden="true" />
                Back to Home
              </button>
            </div>

            <p className="mt-6 text-slate-500 text-sm">
              If this problem persists, please contact support.
            </p>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

/**
 * withErrorBoundary - HOC to wrap a component with an ErrorBoundary
 * 
 * @param {React.Component} Component - Component to wrap
 * @param {Object} props - Props to pass to ErrorBoundary
 * @returns {React.Component} Wrapped component
 * 
 * @example
 * const SafeComponent = withErrorBoundary(MyComponent)
 */
function withErrorBoundary(Component, errorBoundaryProps = {}) {
  return function WrappedComponent(props) {
    return (
      <ErrorBoundary {...errorBoundaryProps}>
        <Component {...props} />
      </ErrorBoundary>
    )
  }
}

export { ErrorBoundary, RouteErrorBoundary, withErrorBoundary }
export default ErrorBoundary

import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

/**
 * MedicationSchedule Component
 * Displays a visual daily medication schedule for a patient
 */
function MedicationSchedule({ medications = [] }) {
    const [schedule, setSchedule] = useState([])
    const [isExpanded, setIsExpanded] = useState(false)
    const [scheduleTimes, setScheduleTimes] = useState({})

    // Time slots for medication schedule
    const timeSlots = [
        { id: 'morning', label: 'Morning', time: '7:00 AM', icon: '­ƒîà' },
        { id: 'afternoon', label: 'Afternoon', time: '12:00 PM', icon: 'ÔÿÇ´©Å' },
        { id: 'evening', label: 'Evening', time: '6:00 PM', icon: '­ƒîå' },
        { id: 'bedtime', label: 'Bedtime', time: '10:00 PM', icon: '­ƒîÖ' },
    ]

    // Initialize schedule from medications
    useEffect(() => {
        if (medications.length > 0) {
            const initialSchedule = {}
            medications.forEach(med => {
                // Parse frequency to suggest time slots
                const freq = (med.frequency || 'once daily').toLowerCase()
                let slots = ['morning']

                if (freq.includes('twice') || freq.includes('2x') || freq.includes('bid')) {
                    slots = ['morning', 'evening']
                } else if (freq.includes('three') || freq.includes('3x') || freq.includes('tid')) {
                    slots = ['morning', 'afternoon', 'evening']
                } else if (freq.includes('four') || freq.includes('4x') || freq.includes('qid')) {
                    slots = ['morning', 'afternoon', 'evening', 'bedtime']
                } else if (freq.includes('bedtime') || freq.includes('night') || freq.includes('hs')) {
                    slots = ['bedtime']
                } else if (freq.includes('morning')) {
                    slots = ['morning']
                }

                initialSchedule[med.drug_name] = {
                    slots,
                    withFood: freq.includes('food') || freq.includes('meal'),
                    notes: med.notes || ''
                }
            })
            setScheduleTimes(initialSchedule)
            buildScheduleView(initialSchedule)
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [medications])

    const buildScheduleView = useCallback((scheduleData) => {
        const scheduleView = timeSlots.map(slot => ({
            ...slot,
            medications: medications.filter(med =>
                scheduleData[med.drug_name]?.slots?.includes(slot.id)
            ).map(med => ({
                ...med,
                withFood: scheduleData[med.drug_name]?.withFood || false
            }))
        }))
        setSchedule(scheduleView)
    }, [medications, timeSlots])

    const toggleTimeSlot = (drugName, slotId) => {
        setScheduleTimes(prev => {
            const current = prev[drugName]?.slots || []
            const newSlots = current.includes(slotId)
                ? current.filter(s => s !== slotId)
                : [...current, slotId]

            const updated = {
                ...prev,
                [drugName]: {
                    ...(prev[drugName] || {}),
                    slots: newSlots
                }
            }
            buildScheduleView(updated)
            return updated
        })
    }

    const toggleWithFood = (drugName) => {
        setScheduleTimes(prev => {
            const updated = {
                ...prev,
                [drugName]: {
                    ...(prev[drugName] || {}),
                    withFood: !(prev[drugName]?.withFood || false)
                }
            }
            buildScheduleView(updated)
            return updated
        })
    }

    if (medications.length === 0) {
        return (
            <div className="p-4 bg-slate-800/50 rounded-xl border border-slate-700/50">
                <p className="text-sm text-slate-400 text-center">
                    No medications to schedule. Add medications to the patient profile first.
                </p>
            </div>
        )
    }

    return (
        <div className="mt-6">
            <button
                onClick={() => setIsExpanded(!isExpanded)}
                className="flex items-center gap-3 text-lg font-semibold text-white mb-4 hover:text-medical-400 transition-colors"
            >
                <span className="text-2xl">­ƒôà</span>
                Medication Schedule
                <svg
                    className={`w-5 h-5 transition-transform ${isExpanded ? 'rotate-180' : ''}`}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
                <span className="text-xs px-2 py-1 bg-medical-500/20 text-medical-400 rounded-full">
                    {medications.length} medications
                </span>
            </button>

            <AnimatePresence>
                {isExpanded && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3 }}
                        className="overflow-hidden"
                    >
                        {/* Timeline View */}
                        <div className="space-y-4 mb-6">
                            {schedule.map((slot, idx) => (
                                <motion.div
                                    key={slot.id}
                                    initial={{ opacity: 0, x: -20 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: idx * 0.1 }}
                                    className={`p-4 rounded-xl border ${slot.medications.length > 0
                                        ? 'bg-slate-800/70 border-medical-500/30'
                                        : 'bg-slate-900/50 border-slate-700/30'
                                        }`}
                                >
                                    <div className="flex items-center gap-3 mb-3">
                                        <span className="text-2xl">{slot.icon}</span>
                                        <div>
                                            <h4 className="font-medium text-white">{slot.label}</h4>
                                            <p className="text-xs text-slate-400">{slot.time}</p>
                                        </div>
                                        <span className={`ml-auto text-xs px-2 py-1 rounded-full ${slot.medications.length > 0
                                            ? 'bg-medical-500/20 text-medical-400'
                                            : 'bg-slate-700 text-slate-500'
                                            }`}>
                                            {slot.medications.length} medications
                                        </span>
                                    </div>

                                    {slot.medications.length > 0 && (
                                        <div className="flex flex-wrap gap-2">
                                            {slot.medications.map((med, mIdx) => (
                                                <div
                                                    key={mIdx}
                                                    className="flex items-center gap-2 px-3 py-2 bg-slate-700/50 rounded-lg border border-slate-600/50"
                                                >
                                                    <span className="text-sm font-medium text-white">{med.drug_name}</span>
                                                    {med.dosage && (
                                                        <span className="text-xs text-slate-400">{med.dosage}</span>
                                                    )}
                                                    {med.withFood && (
                                                        <span className="text-xs px-1.5 py-0.5 bg-amber-500/20 text-amber-400 rounded">
                                                            ­ƒì¢´©Å with food
                                                        </span>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </motion.div>
                            ))}
                        </div>

                        {/* Edit Schedule */}
                        <div className="p-4 bg-slate-800/50 rounded-xl border border-slate-700/50">
                            <h4 className="font-medium text-white mb-3 flex items-center gap-2">
                                <span>ÔÜÖ´©Å</span> Customize Schedule
                            </h4>
                            <div className="space-y-3">
                                {medications.map((med, idx) => (
                                    <div key={idx} className="p-3 bg-slate-900/50 rounded-lg">
                                        <div className="flex items-center justify-between mb-2">
                                            <span className="font-medium text-white">{med.drug_name}</span>
                                            <button
                                                onClick={() => toggleWithFood(med.drug_name)}
                                                className={`text-xs px-2 py-1 rounded transition-colors ${scheduleTimes[med.drug_name]?.withFood
                                                    ? 'bg-amber-500/30 text-amber-400 border border-amber-500/50'
                                                    : 'bg-slate-700 text-slate-400 border border-slate-600'
                                                    }`}
                                            >
                                                ­ƒì¢´©Å With Food
                                            </button>
                                        </div>
                                        <div className="flex gap-2 flex-wrap">
                                            {timeSlots.map(slot => (
                                                <button
                                                    key={slot.id}
                                                    onClick={() => toggleTimeSlot(med.drug_name, slot.id)}
                                                    className={`px-3 py-1 rounded text-xs transition-colors ${scheduleTimes[med.drug_name]?.slots?.includes(slot.id)
                                                        ? 'bg-medical-500/30 text-medical-400 border border-medical-500/50'
                                                        : 'bg-slate-700 text-slate-400 border border-slate-600'
                                                        }`}
                                                >
                                                    {slot.icon} {slot.label}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Timing Tips */}
                        <div className="mt-4 p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl">
                            <h4 className="font-medium text-blue-400 mb-2 flex items-center gap-2">
                                <span>­ƒÆí</span> Timing Tips for Diabetics
                            </h4>
                            <ul className="text-sm text-slate-300 space-y-1">
                                <li>ÔÇó <strong>Metformin:</strong> Take with meals to reduce stomach upset</li>
                                <li>ÔÇó <strong>Sulfonylureas:</strong> Take 30 minutes before meals</li>
                                <li>ÔÇó <strong>SGLT2 inhibitors:</strong> Take in the morning to avoid nighttime urination</li>
                                <li>ÔÇó <strong>Insulin:</strong> Timing depends on type (rapid, long-acting)</li>
                            </ul>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    )
}

export default MedicationSchedule
